  function todayKey(){const d=new Date();return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  function dailyLevel(id=mode){let n=Array.from(todayKey()+id).reduce((a,c)=>((a*31)+c.charCodeAt(0))>>>0,7);return n%100+1}
  function nextLevel(){return Math.min(100,Math.max(1,Number(progress[mode])||1))}
  function syncModeBadges(){document.querySelectorAll('.mode-card').forEach(btn=>{const badge=btn.querySelector('.difficulty');if(badge)badge.textContent='LEVEL '+Math.min(100,Math.max(1,Number(progress[btn.dataset.mode])||1))+'/100'})}
  function renderRecords(){const host=$('record-grid');host.replaceChildren();for(const id of Object.keys(titles)){const chip=document.createElement('div');chip.className='record-chip';const label=document.createElement('span');label.textContent=titles[id].toUpperCase();const value=document.createElement('strong');value.textContent=best[id]?String(best[id]):'No record';chip.append(label,value);host.append(chip)}}
