  function refreshDailyButton(){const b=$('daily-challenge');if(!b)return;const done=dailyDone[`${todayKey()}:${mode}`];b.textContent=done?`Daily cleared · Level ${dailyLevel()}`:`Daily challenge · Level ${dailyLevel()}`;b.title=`One special ${titles[mode]} level picked for today. Resets tomorrow.`}


