  function setMode(next){if(!titles[next])return;if(document.body.classList.contains('is-game-fullscreen'))leaveFullscreen();runToken++;mode=next;ensureModeAssets(mode);$('roadster-steering').hidden=mode!=='roadster';$('wok-steering').hidden=mode!=='wok';$('tea-controls').hidden=mode!=='teatoss';document.body.dataset.game=mode;document.querySelectorAll('.mode-card').forEach(btn=>{const active=btn.dataset.mode===mode;btn.classList.toggle('is-selected',active);btn.setAttribute('aria-pressed',String(active));const label=btn.querySelector('.difficulty');if(label)label.textContent=`LEVEL ${progress[btn.dataset.mode]||1}/100`});$('game-title').textContent=titles[mode];$('game-rule').textContent=rules[mode];$('control-copy').textContent=controls[mode];const how=instructions[mode],list=$('instruction-steps');list.replaceChildren(...how.map(text=>{const li=document.createElement('li');li.textContent=text;return li}));$('instruction-controls').textContent=controls[mode];$('power-guide').textContent=powerGuide[mode];$('overlay-icon').textContent=icons[mode];$('overlay-kicker').textContent=`100 LEVELS · ${titles[mode].toUpperCase()}`;$('overlay-title').textContent=overlayTitle(mode);$('overlay-copy').textContent=`${overlayCopy(mode)} Every tenth level is a boss round with an AI-generated rival and a tougher objective. New power-ups unlock at Levels 4 and 7; you earn charges as you clear levels.`;$('start-game').textContent=`Continue ${titles[mode]} · Level ${nextLevel()}`;$('power-button').disabled=true;bestEl.textContent=String(best[mode]||0);clockEl.textContent=`${nextLevel()} / 100`;statusEl.textContent=`${titles[mode]} selected. Continue at Level ${nextLevel()} of 100; every tenth level is a boss.`;state=null;overlay.hidden=false;syncHud();updatePowerUI();renderRecords();renderBadges();refreshDailyButton();drawAttract()}
  function overlayTitle(m){return {noodle:'Catch food. Dodge chili bombs.',match:'Remember every dish. Find the pairs.',roadster:'Pick a lane and commit.',trailblazer:'Memorize the path.',ace:'Wait for the perfect window.',wok:'Follow the ticket. Sort the wok.',lantern:'Find the leaves. Outsmart the spirits.',teatoss:'Lead the cup. Land the toss.'}[m]}
  function overlayCopy(m){return {noodle:'Move the bowl under any falling food to fill the counter. Catch the target number to clear the level. Avoid red chili bombs: they cost a heart. Missed food is safe, and there is no recipe sequence. Each level adds a food catch and increases the fall speed.',match:'Flip over two cards at a time and memorize each dish. Pairs stay revealed; mismatches turn back. Match every pair within the move limit to clear the level. Boards grow from three pairs to eight, with more moves to plan and less time to study the preview.',roadster:'Switch lanes to collect glowing flavor tokens and avoid trucks. Clear each level by getting its token target before time runs out. Later levels increase speed, traffic, and the number of tokens needed.',trailblazer:'Study the numbered route, then tap those tiles in order after they hide. Every next tile must touch an edge. Each level adds route steps, shortens the preview, and gives you less time.',ace:'Time each strike so the red needle tip lands inside the moving gold arc. Clear each level by hitting its target before three misses. Later levels speed up the needle and make the gold arc smaller.',wok:'Three clear lanes show falling ingredients. Check the illustrated order ticket, switch lanes with the buttons or arrows, and catch matching ingredients while avoiding wrong food and chilies.',lantern:'Move one neighboring garden tile at a time. The lantern glows on your current tile, tea leaves sparkle at their destination, and the spirits patrol the garden. Plan short moves to collect every leaf before time runs out.',teatoss:'Drag upward from the teapot to preview and throw. The dotted flight arc shows where the tea will travel, while the cup slides across the upper garden. Lead the cup and adjust the pull to land each toss.'}[m]}
  function resize(){const r=canvas.getBoundingClientRect();if(!r.width)return;const dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.round(960*dpr);canvas.height=Math.round(540*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(!state)drawAttract()}
  function drawAttract(){drawBase();ctx.save();ctx.fillStyle='#09251fc9';ctx.beginPath();ctx.roundRect(170,220,620,108,20);ctx.fill();ctx.textAlign='center';ctx.shadowColor='#0009';ctx.shadowBlur=12;ctx.fillStyle='#fff3be';ctx.font='800 34px Inter,system-ui';ctx.fillText(`${icons[mode]}  ${titles[mode]}`,480,268);ctx.shadowBlur=0;ctx.fillStyle='#fff';ctx.font='600 17px Inter,system-ui';ctx.fillText('Select a challenge above, then press Start.',480,305);ctx.restore()}
