    const palettes={noodle:['#d5f5d5','#9fd69c'],match:['#ffe994','#f1b94f'],roadster:['#16462f','#32754a'],trailblazer:['#d6ed9d','#73b568'],ace:['#f8df70','#ed9850']},colors=palettes[mode]||palettes.noodle,g=ctx.createLinearGradient(0,0,960,540);
