  function drawMatch(){const s=state,left=282,top=62,cell=90,gap=12;ctx.textAlign='center';ctx.fillStyle='#fff8d8';ctx.font='800 19px Inter';ctx.fillText(`${s.boss?'BOSS MATCH · ':''}LEVEL ${s.level}/100  ·  MATCH ${s.pairs} DISH PAIRS`,480,31);ctx.font='700 13px Inter';ctx.fillStyle='#e4f5c9';ctx.fillText(`${Math.max(0,s.maxMoves-s.moves)} MOVES LEFT`,480,51);for(let i=0;i<s.cards.length;i++){const row=Math.floor(i/4),col=i%4,x=left+col*(cell+gap),y=top+row*(cell+gap),open=s.time<s.previewUntil||s.flipped.includes(i)||s.matched.has(i)||s.peekUntil>s.time;ctx.save();ctx.shadowColor=s.matched.has(i)?'#f3e876':'#071d1855';ctx.shadowBlur=s.cursor===i?21:10;ctx.shadowOffsetY=5;const tile=ctx.createLinearGradient(x,y,x+cell,y+cell);tile.addColorStop(0,open?(s.matched.has(i)?'#c5f27c':'#fff1aa'):'#e94638');tile.addColorStop(1,open?(s.matched.has(i)?'#42b95f':'#f0c64e'):'#a6192e');ctx.fillStyle=tile;ctx.beginPath();ctx.roundRect(x,y,cell,cell,15);ctx.fill();ctx.shadowColor='transparent';ctx.lineWidth=s.cursor===i?5:2;ctx.strokeStyle=s.cursor===i?'#fff6a0':'#ffffffad';ctx.stroke();ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=open?'43px system-ui':'700 31px Georgia,serif';ctx.fillStyle='#fff';if(open){const sprite=dishSprites[dishSpriteByEmoji[s.cards[i]]],size=cell*.67;if(sprite?.complete&&sprite.naturalWidth)ctx.drawImage(sprite,x+(cell-size)/2,y+(cell-size)/2,size,size);else ctx.fillText(s.cards[i],x+cell/2,y+cell/2+2)}else ctx.fillText('✦',x+cell/2,y+cell/2+2);ctx.restore()}ctx.textBaseline='alphabetic';if(s.time<s.previewUntil){ctx.fillStyle='#fff';ctx.font='700 14px Inter';ctx.fillText(`MEMORIZE THE BOARD · ${Math.ceil(s.previewUntil-s.time)}s`,480,520)}else{ctx.fillStyle='#fff';ctx.font='700 13px Inter';ctx.fillText('REMEMBER THEIR PLACES · MATCH TWO',480,520)}}
  function drawRoadster(){
    const s=state;
    if(!sceneImages.roadster?.complete||!sceneImages.roadster.naturalWidth){ctx.fillStyle='#b63a32';ctx.fillRect(150,0,660,540);ctx.fillStyle='#153b29';ctx.fillRect(168,0,624,540);const shine=ctx.createLinearGradient(168,0,792,0);shine.addColorStop(0,'#2d6340');shine.addColorStop(.5,'#19452f');shine.addColorStop(1,'#2d6340');ctx.fillStyle=shine;ctx.fillRect(168,0,624,540);ctx.strokeStyle='#f5d456';ctx.lineWidth=4;ctx.setLineDash([24,24]);for(const x of [376,584]){ctx.beginPath();ctx.moveTo(x,-40+(s.time*270)%48);ctx.lineTo(x,580);ctx.stroke()}ctx.setLineDash([])}
    if(s.boss){ctx.save();ctx.fillStyle='#9e2529';ctx.globalAlpha=.22+.18*Math.sin(s.time*9);ctx.fillRect(150,0,660,540);ctx.restore()}for(const o of s.objects){const x=272+o.lane*208;ctx.save();ctx.translate(x,o.y);if(o.type==='traffic'){const vehicle=vehicleSprites[o.sprite||2];ctx.shadowColor='#ffcf56';ctx.shadowBlur=12;if(vehicle?.complete&&vehicle.naturalWidth)ctx.drawImage(vehicle,-31,-47,62,94);else{ctx.font='48px system-ui';ctx.textAlign='center';ctx.fillText('🚚',0,16)}}else{ctx.shadowColor='#ffe37a';ctx.shadowBlur=17;if(flavorTokenSprite?.complete&&flavorTokenSprite.naturalWidth)ctx.drawImage(flavorTokenSprite,-25,-25,50,50);else{ctx.font='40px system-ui';ctx.textAlign='center';ctx.fillText('✨',0,14)}}ctx.restore()}
    ctx.save();ctx.strokeStyle='#f8e7a5';ctx.lineWidth=5;ctx.setLineDash([30,24]);ctx.lineDashOffset=-(s.roadOffset||0)%54;for(const x of [376,584]){ctx.beginPath();ctx.moveTo(x,-20);ctx.lineTo(x,560);ctx.stroke()}ctx.setLineDash([]);ctx.restore();
    ctx.save();ctx.translate(272+(s.laneX??s.lane)*208,464+Math.sin(s.time*12)*2);ctx.rotate(clamp((s.lane-(s.laneX??s.lane))*.16,-.16,.16));ctx.shadowColor='#b8ffe0';ctx.shadowBlur=25+Math.sin(s.time*10)*5;const racer=vehicleSprites[0];if(racer?.complete&&racer.naturalWidth)ctx.drawImage(racer,-38,-56,76,112);else{ctx.font='52px system-ui';ctx.textAlign='center';ctx.fillText('🏎️',0,16)}ctx.restore();ctx.save();ctx.fillStyle='#09251fd8';ctx.beginPath();ctx.roundRect(322,12,316,37,12);ctx.fill();ctx.fillStyle='#fff4c1';ctx.font='800 16px Inter';ctx.textAlign='center';ctx.fillText(`${s.boss?'BOSS RACE · ':''}LEVEL ${s.level}/100 · TOKENS ${s.tokens}/${s.goalTokens}`,480,36);ctx.restore()
  }
  function drawTrail(){const s=state,cell=80,gap=8,left=264,top=54;ctx.textAlign='center';ctx.fillStyle='#174b35';ctx.font='800 17px Inter';ctx.fillText(s.preview>0?'MEMORIZE THE NUMBERED PATH':`ROUTE ${s.round} · STEP ${s.step+1} OF ${s.route.length}`,480,28);for(let i=0;i<25;i++){const row=Math.floor(i/5),col=i%5,x=left+col*(cell+gap),y=top+row*(cell+gap),routeIndex=s.route.indexOf(i);ctx.fillStyle='#fffef0df';ctx.shadowColor='#174b3544';ctx.shadowBlur=8;ctx.fillRect(x,y,cell,cell);ctx.shadowBlur=0;ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.strokeRect(x,y,cell,cell);let shown=s.preview>0?routeIndex>=0:i===s.cell;if(s.hintUntil>s.time&&i===s.route[s.step])shown=true;if(shown){const tile=ctx.createLinearGradient(x,y,x+cell,y+cell);tile.addColorStop(0,s.preview>0?'#ffe078':i===s.cell?'#91df72':'#f2cd52');tile.addColorStop(1,s.preview>0?'#ffad65':i===s.cell?'#42a957':'#c84435');ctx.fillStyle=tile;ctx.fillRect(x+5,y+5,cell-10,cell-10);ctx.font='34px system-ui';ctx.fillStyle='#322450';if(s.preview>0)ctx.fillText(String(routeIndex+1),x+cell/2,y+62);else if(i===s.route[0]||i===s.route.at(-1)){const art=dishSprites[i===s.route[0]?1:0];if(art?.complete&&art.naturalWidth)ctx.drawImage(art,x+15,y+15,cell-30,cell-30);else ctx.fillText(i===s.route[0]?'🏁':'🍜',x+cell/2,y+62)}else ctx.fillText('✦',x+cell/2,y+62)}else if(s.preview<=0){ctx.font='17px Inter';ctx.fillStyle='#9a91a8';ctx.fillText('?',x+cell/2,y+61)}}ctx.fillStyle='#174b35';ctx.font='800 13px Inter';ctx.fillText('ONLY NEIGHBORING TILES COUNT',480,530)}
  function drawAce(){const s=state,cx=480,cy=282,r=170,window=s.wideWindowUntil>s.time?Math.min(.32,s.window*1.8):s.window;ctx.textAlign='center';ctx.fillStyle='#185b49';ctx.font='800 18px Inter';ctx.fillText(`LEVEL ${s.level}/100 · HIT ${s.goalHits} TARGETS`,480,38);ctx.fillStyle='#fff8e8';ctx.beginPath();ctx.arc(cx,cy,r+20,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b8a678';ctx.lineWidth=2;ctx.stroke();ctx.beginPath();ctx.strokeStyle='#d5b252';ctx.lineWidth=18;ctx.arc(cx,cy,r,s.target-window,s.target+window);ctx.stroke();ctx.strokeStyle='#1b5442';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx+Math.cos(s.angle)*r,cy+Math.sin(s.angle)*r);ctx.stroke();ctx.fillStyle='#ac392f';ctx.beginPath();ctx.arc(cx+Math.cos(s.angle)*r,cy+Math.sin(s.angle)*r,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#165b48';ctx.beginPath();ctx.arc(cx,cy,24,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.font='700 18px Inter';ctx.fillText(`${s.hits}/${s.goalHits}`,cx,cy+6);ctx.fillStyle='#225f4b';ctx.font='700 15px Inter';ctx.fillText(`WINDOW  ±${(window*57.3).toFixed(1)}°`,480,510)}
  function clamp(v,min,max){return Math.max(min,Math.min(max,v))}
  document.querySelectorAll('.mode-card').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));$('start-game').addEventListener('click',handleStart);$('restart-game').addEventListener('click',()=>start(true));$('daily-challenge').addEventListener('click',()=>{$('practice-mode').checked=false;start(false,{daily:true,level:dailyLevel()})});$('practice-mode').addEventListener('change',()=>{statusEl.textContent=$('practice-mode').checked?'Practice mode is on for the next run. It will not change hearts, saved levels, or high scores.':'Practice mode is off for the next run.'});$('power-button').addEventListener('click',power);$('power-select').addEventListener('change',()=>{selectedPower[mode]=$('power-select').value;updatePowerUI()});exitFullscreenButton.addEventListener('click',leaveFullscreen);exitGameButton.addEventListener('click',exitGame);$('steer-left').addEventListener('click',()=>{if(state?.live&&mode==='roadster')state.lane=Math.max(0,state.lane-1)});$('steer-right').addEventListener('click',()=>{if(state?.live&&mode==='roadster')state.lane=Math.min(2,state.lane+1)});document.querySelectorAll('[data-wok-lane]').forEach(button=>button.addEventListener('click',()=>{if(state?.live&&mode==='wok')state.lane=Number(button.dataset.wokLane)}));document.querySelectorAll('[data-aim]').forEach(button=>button.addEventListener('click',()=>{if(!state?.live||mode!=='teatoss')return;const action=button.dataset.aim;if(action==='left')state.aimAngle-=.08;if(action==='right')state.aimAngle+=.08;if(action==='power')state.aimPower=Math.min(600,state.aimPower+35);if(action==='less')state.aimPower=Math.max(180,state.aimPower-35);if(action==='throw'&&!state.projectile){state.projectile={x:480,y:440,vx:Math.cos(state.aimAngle)*state.aimPower,vy:Math.sin(state.aimAngle)*state.aimPower,trail:[]}}}));document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&document.body.classList.contains('is-game-fullscreen')){document.body.classList.remove('is-game-fullscreen');exitFullscreenButton.hidden=true;exitGameButton.hidden=true;requestAnimationFrame(resize)}});canvas.addEventListener('pointerdown',pointerDown);canvas.addEventListener('pointermove',pointerMove);canvas.addEventListener('pointerup',pointerUp);canvas.addEventListener('pointercancel',pointerUp);window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);window.addEventListener('blur',()=>keys.clear());window.addEventListener('resize',resize);resize();const requestedGame=new URLSearchParams(window.location.search).get('game');if(requestedGame&&titles[requestedGame]){setMode(requestedGame);handleStart()}else setMode('noodle');
